	/* @Override */
	public bool accepts(Symbol symbol, Program program) {
		if (acceptsAll) {
			return true;
		}
		if (!isAcceptableOrigin(program, symbol)) {
			return false;
		}
		if (!isAcceptableType(program, symbol)) {
			return false;
		}
		if (!passesAdvancedFilters(program, symbol)) {
			return false;
		}
		return true;
	}

	private bool isAcceptableOrigin(Program program, Symbol symbol) {
		if (acceptsAllSources) {
			return true;
		}
		foreach (Filter activeOriginFilter in activeOriginFilters) {
			if (activeOriginFilter.matches(program, symbol)) {
				return true;
			}
		}
		return false;
	}

	private bool isAcceptableType(Program program, Symbol symbol) {
		if (acceptsAllTypes) {
			return true;
		}
		foreach (Filter activeTypeFilter in activeTypeFilters) {
			if (activeTypeFilter.matches(program, symbol)) {
				return true;
			}
		}
		return false;
	}

	private bool passesAdvancedFilters(Program program, Symbol symbol) {
		bool applicable = false;
		foreach (AdvancedFilter activeAdvancedFilter in activeAdvancedFilters) {
			if (activeAdvancedFilter.isApplicable(symbol)) {
				applicable = true;
				if (activeAdvancedFilter.matches(program, symbol)) {
					return true;
				}
			}
		}
		if (!applicable) { // if none of the filters were applicable, then the symbol passes.
			return true;
		}
		return false;
	}

	/* @Override */
