	private abstract static class AdvancedFilter : Filter {

		private static readonly string ADVANCED_ELEMENT_NAME = "ADVANCED_FILTER";

		List<Filter> applicableFilters = new();

		AdvancedFilter(string name) : base(name, false, false)
    {
		}

		abstract bool isApplicable(Symbol s);

		void addApplicableFilter(Filter filter) {
			applicableFilters.add(filter);
		}

		/* @Override */
		bool isEnabled() {
			foreach (Filter filter in applicableFilters) {
				if (filter.isActive()) {
					return true;
				}
			}
			return false;
		}

		/* @Override */
		Element saveToXml() {
			/*
			 	<ADVANCED_FILTER NAME="foo" 
			 	                
					<FILTER NAME="one" 	
							ACTIVE="false" 
							INCLUDES_DEFAULTS="true" 
							ONLY_CODE_SYMBOLS="false" />
							
					<FILTER NAME="two" 	
							ACTIVE="false" 
							INCLUDES_DEFAULTS="true" 
							ONLY_CODE_SYMBOLS="false" />
			 	                
			 	</ADVANCED_FILTER>
			 */

			Element element = new Element(ADVANCED_ELEMENT_NAME);
			element.setAttribute(NAME_ATTRIBUTE, name);
			element.setAttribute(ACTIVE_ATTRIBUTE, Boolean.toString(active));

			foreach (Filter subFilter in applicableFilters) {
				Element subElement = subFilter.saveToXml();
				element.addContent(subElement);
			}

			return element;
		}

		/* @Override */
		void restoreFromXml(Element element) {
			if (!ADVANCED_ELEMENT_NAME.equals(element.getName())) {
				Msg.error(this, "Incorrect xml stored for filter: " + name);
				return;
			}

			string nameValue = element.getAttributeValue(NAME_ATTRIBUTE);
			if (nameValue == null) {
				Msg.error(this, "No name found for xml element: " + name);
				return;
			}

			this.name = nameValue;
			this.active = parseBooleanAttribute(element, ACTIVE_ATTRIBUTE);

			/* @SuppressWarnings("unchecked") */
			List<Element> children = element.getChildren();
			foreach (Element child in children) {
				string childName = child.getAttributeValue(Filter.NAME_ATTRIBUTE);
				Filter childFilter = getFilter(childName);
				if (childFilter == null) {
					Msg.error(this, "Unable to locate advanced sub-filter: " + childName);
					continue; // shouldn't happen
				}

				childFilter.restoreFromXml(child);
			}

		}

		private Filter getFilter(string childName) {
			foreach (Filter filter in applicableFilters) {
				if (filter.getName().equals(childName)) {
					return filter;
				}
			}
			return null;
		}

	}

	private abstract static class Filter {

		protected static readonly string ELEMENT_NAME = "FILTER";
		protected static readonly string NAME_ATTRIBUTE = "NAME";
		protected static readonly string ACTIVE_ATTRIBUTE = "ACTIVE";
		protected static readonly string INCLUDES_DEFAULTS_ATTRIBUTE = "INCLUDES_DEFAULTS";
		protected static readonly string ONLY_CODE_SYMBOLS_ATTRIBUTE = "ONLY_CODE_SYMBOLS";

		protected string name;
		protected bool active;
		private bool includesDefaults;
		private bool onlyCodeSymbols;

		Filter(string name, bool includesDefaults, bool onlyCodeSymbols) {
			this.name = name;
			this.includesDefaults = includesDefaults;
			this.onlyCodeSymbols = onlyCodeSymbols;
		}

		abstract bool matches(Program program, Symbol symbol);

		abstract string getDescription();

		Element saveToXml() {
			/*
			 	<FILTER NAME="foo" ACTIVE="false" INCLUDES_DEFAULTS="true" ONLY_CODE_SYMBOLS="false" />
			 */

			Element element = new Element(ELEMENT_NAME);
			element.setAttribute(NAME_ATTRIBUTE, name);
			element.setAttribute(ACTIVE_ATTRIBUTE, Boolean.toString(active));
			element.setAttribute(INCLUDES_DEFAULTS_ATTRIBUTE, Boolean.toString(includesDefaults));
			element.setAttribute(ONLY_CODE_SYMBOLS_ATTRIBUTE, Boolean.toString(onlyCodeSymbols));
			return element;
		}

		void restoreFromXml(Element element) {
			string nameValue = element.getAttributeValue(NAME_ATTRIBUTE);
			if (nameValue == null) {
				Msg.error(this, "No name found for xml element: " + name);
				return;
			}

			this.name = nameValue;
			this.active = parseBooleanAttribute(element, ACTIVE_ATTRIBUTE);
			this.includesDefaults = parseBooleanAttribute(element, INCLUDES_DEFAULTS_ATTRIBUTE);
			this.onlyCodeSymbols = parseBooleanAttribute(element, ONLY_CODE_SYMBOLS_ATTRIBUTE);
		}

		protected bool parseBooleanAttribute(Element element, string attributeName) {
			string value = element.getAttributeValue(attributeName, Boolean.FALSE.toString());
			return Boolean.parseBoolean(value);
		}

		bool isEnabled() {
			return true;
		}

		string getName() {
			return name;
		}

		bool isActive() {
			return active;
		}

		void setActive(bool b) {
			active = b;
		}
	}


	internal class _Anon_Filter_1 : Filter
	{
		public _Anon_Filter_1() : @base("Default (Labels)", true, false) {}

			/* @Override */
			bool matches(Program program, Symbol symbol) {
				return symbol.getSymbolType() != SymbolType.FUNCTION &&
					symbol.getSource() == SourceType.DEFAULT;
			}

			/* @Override */
			string getDescription() {
				return "Include Symbols that have default names.";
			}

		
	}


	internal class _Anon_Filter_2 : Filter
	{
		public _Anon_Filter_2() : @base("Default (Functions)", true, false) {}

			/* @Override */
			bool matches(Program program, Symbol symbol) {
				return symbol.getSymbolType() == SymbolType.FUNCTION &&
					symbol.getSource() == SourceType.DEFAULT;
			}

			/* @Override */
			string getDescription() {
				return "Include Symbols that have default names.";
			}
		
	}


	internal class _Anon_Filter_3 : Filter
	{
		public _Anon_Filter_3() : @base("Instruction Labels", true, true) {}

			/* @Override */
			bool matches(Program program, Symbol symbol) {
				if (symbol.getSymbolType() == SymbolType.LABEL && !symbol.isExternal()) {
					if (acceptsAllLabels) {
						return true;
					}
					Listing l = program.getListing();
					Address addr = symbol.getAddress();
					CodeUnit cu = l.getCodeUnitContaining(addr);
					if (cu == null) {
						return true;
					}
					if (cu is Instruction) {	// only include if no function 
						return program.getFunctionManager().getFunctionAt(addr) == null;
					}
				}
				return false;
			}

			/* @Override */
			string getDescription() {
				return "Include labels on instructions.";
			}
		
	}


	internal class _Anon_Filter_4 : Filter
	{
		public _Anon_Filter_4() : @base("Data Labels", true, true) {}

			/* @Override */
			bool matches(Program program, Symbol symbol) {
				if (symbol.getSymbolType() == SymbolType.LABEL) {
					if (acceptsAllLabels || symbol.isExternal()) {
						return true;
					}
					Listing l = program.getListing();
					Address addr = symbol.getAddress();
					CodeUnit cu = l.getCodeUnitContaining(addr);
					if (cu == null) {
						return true;
					}
					if (cu is Data) {
						return program.getFunctionManager().getFunctionAt(addr) == null;
					}
				}
				return false;
			}

			/* @Override */
			string getDescription() {
				return "Include labels on Data.";
			}

		
	}


	internal class _Anon_Filter_5 : Filter
	{
		public _Anon_Filter_5() : @base("Function Labels", false, true) {}

			/* @Override */
			bool matches(Program program, Symbol symbol) {
				if (symbol.getSymbolType() == SymbolType.LABEL && !symbol.isExternal()) {
					if (acceptsAllLabels) {
						return true;
					}
					return program.getFunctionManager().getFunctionAt(symbol.getAddress()) != null;
				}
				return (symbol.getSymbolType() == SymbolType.FUNCTION);
			}

			/* @Override */
			string getDescription() {
				return "Include Labels at function entry points";
			}
		
	}


