				return symbol.isExternalEntryPoint();
			}

			/* @Override */
			bool isApplicable(Symbol symbol) {
				SymbolType type = symbol.getSymbolType();
				return type == SymbolType.LABEL || type == SymbolType.FUNCTION;
			}

