					"This Filter only affects label and function symbols";
			}
		
	}


	internal class _Anon_AdvancedFilter_22 : AdvancedFilter
	{
		public _Anon_AdvancedFilter_22() : @base("Subroutines") {}

			/* @Override */
			bool matches(Program program, Symbol symbol) {
				Reference[] refs = symbol.getReferences(null);
				foreach (Reference @ref in refs) {
					if (@ref.getReferenceType().isCall()) {
						return true;
					}
				}
				return false;
			}

			/* @Override */
			bool isApplicable(Symbol symbol) {
				SymbolType type = symbol.getSymbolType();
				return type == SymbolType.LABEL;
			}

			/* @Override */
			string getDescription() {
				return "Include labels that are \"called\" by some instruction.\n" +
					"This Filter only affects label symbols.";
			}
		
	}


